/**
 * ASTNUM language registry — 160 languages.
 *
 * Every language below is selectable in-app. Dictionaries for languages
 * beyond the English/Arabic base are generated by `scripts/i18n/generate.ts`
 * and lazy-loaded per language (see `dictionaries.ts`). Missing keys fall
 * back through the chain:  own dict → base-language dict (regional variants)
 * → English.
 *
 * Design notes:
 * - Codes follow BCP-47 where an ISO code exists (ISO 639-1 preferred,
 *   639-3 for the rest).
 * - v1.23 dedup pass: regional variants that only mirror a base language
 *   already present were removed (ar-EG, zh-Hans, pt-BR, es-MX, es-AR,
 *   prs/Dari, dcr/Negerhollands, tcs) — 168 → 160, zero duplicates.
 * - `intl` is the locale handed to Intl APIs (digits, dates, plurals). For
 *   languages without CLDR data it points to a sensible parent so numbers
 *   still render (never throws — format.ts try/catches anyway).
 * - Native names are endonyms written in the language's own script — no
 *   flags (languages are not countries), matching professional l10n.
 * - RTL lists every right-to-left script language offered.
 */

export type LanguageRegion =
  | "africa"
  | "americas"
  | "asia"
  | "europe"
  | "mena"
  | "oceania"
  | "constructed";

export interface LanguageMeta {
  /** unique registry code (also the dictionary key + persisted value) */
  code: string;
  /** English name (shown as secondary line in the picker) */
  english: string;
  /** endonym in the language's own script */
  native: string;
  /** BCP-47 locale for Intl formatting */
  intl: string;
  /** right-to-left script */
  rtl?: boolean;
  region: LanguageRegion;
  /** shown in the "Popular" row of the language sheet */
  featured?: boolean;
  /** base language this variant falls back to before English */
  fallback?: string;
}

