/* ── Lookups ──────────────────────────────────────────────────────── */

export const LANG_MAP: ReadonlyMap<string, LanguageMeta> = new Map(
  LANGUAGES.map((l) => [l.code, l])
);

export const LANGUAGES_COUNT = LANGUAGES.length;

/** Default (base) language of the app — every key is guaranteed in it. */
export const BASE_LANG = "en" as const;

/** Fallback chain terminator for regional variants. */
export function getLangMeta(code: string): LanguageMeta | undefined {
  return LANG_MAP.get(code);
}

export function isKnownLang(code: string): boolean {
  return LANG_MAP.has(code);
}

/** Normalize anything persisted/transported into a registry code. */
export function safeLang(code: unknown): string {
  return typeof code === "string" && isKnownLang(code) ? code : BASE_LANG;
}

export function isRtlLang(code: string): boolean {
  return LANG_MAP.get(code)?.rtl === true;
}

/** Arabic-script UIs render the Arabic percent sign ٪ */
export function isArabicDigitsLang(code: string): boolean {
  return code === "ar" || code === "nub";
}

/** BCP-47 locale for Intl formatting (own → fallback → en-US). */
export function localeFor(code: string): string {
  const meta = LANG_MAP.get(code);
  if (meta) return meta.intl;
  // unknown codes (e.g. legacy "ar"/"en" always resolve above) → English
  return "en-US";
}

/** The language's own name, guaranteed non-empty (falls to English name). */
export function nativeName(code: string): string {
  return LANG_MAP.get(code)?.native ?? code;
}

export const FEATURED_LANGUAGES: LanguageMeta[] = LANGUAGES.filter(
  (l) => l.featured
);

